INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('005700e7-9d90-4508-adfb-7d96f52358d3', 'real_estate', NULL, 'What is market value?', '¿Qué es el valor de mercado?', '["The most probable price a property would bring in an open market", "The assessed value for taxes", "The insurance value", "The purchase price"]', '["El precio más probable que una propiedad alcanzaría en un mercado abierto", "El valor tasado para impuestos", "El valor del seguro", "El precio de compra"]', 0, 'Market value is the most probable price a property would sell for in a competitive, open market with a knowledgeable buyer and seller.', 'El valor de mercado es el precio más probable por el que una propiedad se vendería en un mercado competitivo y abierto con compradores y vendedores informados.', true, '2026-01-14 18:28:35.369562', '2026-01-14 18:28:35.369562') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('022882d4-57b0-4b26-85c6-c5dbbfe8a359', 'real_estate', NULL, 'What is a property manager''s primary responsibility?', '¿Cuál es la responsabilidad principal de un administrador de propiedades?', '["To manage property on behalf of the owner to maximize return on investment", "To sell the property", "To appraise the property", "To finance the property"]', '["Administrar la propiedad en nombre del propietario para maximizar el retorno de la inversión", "Vender la propiedad", "Tasar la propiedad", "Financiar la propiedad"]', 0, 'A property manager''s primary duty is to manage property on behalf of the owner, including tenant relations, maintenance, and maximizing income.', 'El deber principal de un administrador de propiedades es administrar la propiedad en nombre del propietario, incluyendo relaciones con inquilinos, mantenimiento y maximizar ingresos.', true, '2026-01-14 22:36:13.39809', '2026-01-14 22:36:13.39809') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('03537271-c0a6-4bc7-8d84-3c47f3b9395d', 'real_estate', NULL, 'What is the loan estimate?', '¿Qué es el estimado de préstamo?', '["A form detailing estimated loan terms and costs within 3 days of application", "A final closing document", "An appraisal report", "A title search"]', '["Un formulario que detalla términos y costos estimados del préstamo dentro de 3 días de la solicitud", "Un documento final de cierre", "Un informe de tasación", "Una búsqueda de título"]', 0, 'The Loan Estimate is a three-page form lenders must provide within 3 business days of receiving a mortgage application.', 'El Estimado de Préstamo es un formulario de tres páginas que los prestamistas deben proporcionar dentro de 3 días hábiles de recibir una solicitud de hipoteca.', true, '2026-01-14 18:28:35.541413', '2026-01-14 18:28:35.541413') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('04fefd63-5452-4c2a-a2b7-456f14b317fc', 'real_estate', NULL, 'How long does an applicant have to pass the Texas real estate exam after completing the required education?', '¿Cuánto tiempo tiene un solicitante para aprobar el examen de bienes raíces de Texas después de completar la educación requerida?', '["1 year", "2 years", "6 months", "18 months"]', '["1 año", "2 años", "6 meses", "18 meses"]', 0, 'Applicants have one year from the date TREC approves their application to pass the licensing examination.', 'Los solicitantes tienen un año desde la fecha en que TREC aprueba su solicitud para aprobar el examen de licencia.', true, '2026-01-14 22:36:12.982157', '2026-01-14 22:36:12.982157') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0938a4fc-75cf-4ee6-8759-b54036a68bea', 'real_estate', NULL, 'What is the Fair Housing Act?', '¿Qué es la Ley de Vivienda Justa?', '["A federal law prohibiting discrimination in housing", "A Texas state law", "A zoning regulation", "A mortgage law"]', '["Una ley federal que prohíbe la discriminación en vivienda", "Una ley estatal de Texas", "Una regulación de zonificación", "Una ley hipotecaria"]', 0, 'The Fair Housing Act prohibits discrimination in housing based on race, color, religion, sex, national origin, familial status, or disability.', 'La Ley de Vivienda Justa prohíbe la discriminación en vivienda basada en raza, color, religión, sexo, origen nacional, estado familiar o discapacidad.', true, '2026-01-14 18:28:35.528087', '2026-01-14 18:28:35.528087') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('09887f1d-27b1-4c81-b3a5-d8a937c1e96d', 'real_estate', NULL, 'What is a contingency in a real estate contract?', '¿Qué es una contingencia en un contrato de bienes raíces?', '["A condition that must be met for the contract to be binding", "A guarantee of closing", "An automatic approval", "A penalty clause"]', '["Una condición que debe cumplirse para que el contrato sea vinculante", "Una garantía de cierre", "Una aprobación automática", "Una cláusula de penalidad"]', 0, 'A contingency is a condition that must be satisfied for the contract to become fully binding.', 'Una contingencia es una condición que debe satisfacerse para que el contrato sea completamente vinculante.', true, '2026-01-14 22:36:13.069119', '2026-01-14 22:36:13.069119') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0ab8e55f-2097-47f2-932d-5a924d08dbdc', 'real_estate', NULL, 'What is loan-to-value ratio (LTV)?', '¿Qué es la relación préstamo-valor (LTV)?', '["The loan amount divided by the property value", "The monthly payment amount", "The interest rate", "The closing costs"]', '["El monto del préstamo dividido por el valor de la propiedad", "El monto del pago mensual", "La tasa de interés", "Los costos de cierre"]', 0, 'LTV is calculated by dividing the loan amount by the appraised value of the property, used to assess lending risk.', 'El LTV se calcula dividiendo el monto del préstamo por el valor tasado de la propiedad, utilizado para evaluar el riesgo de préstamo.', true, '2026-01-14 18:28:35.3873', '2026-01-14 18:28:35.3873') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0d2b74a1-a310-4373-8044-d26119f3ed64', 'real_estate', NULL, 'What is the Texas Property Code requirement for seller''s disclosure?', '¿Cuál es el requisito del Código de Propiedad de Texas para la divulgación del vendedor?', '["Sellers must disclose known defects to buyers", "No disclosure is required", "Only structural defects need disclosure", "Only environmental hazards need disclosure"]', '["Los vendedores deben divulgar defectos conocidos a los compradores", "No se requiere divulgación", "Solo los defectos estructurales necesitan divulgación", "Solo los peligros ambientales necesitan divulgación"]', 0, 'Texas law requires sellers of residential property to provide buyers with a Seller''s Disclosure Notice revealing known material defects.', 'La ley de Texas requiere que los vendedores de propiedades residenciales proporcionen a los compradores un Aviso de Divulgación del Vendedor revelando defectos materiales conocidos.', true, '2026-01-14 18:28:35.454513', '2026-01-14 18:28:35.454513') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0d3ce6e6-5c4a-40fa-bfe1-a0d1af134c4c', 'real_estate', NULL, 'What is the purpose of the Texas Real Estate Recovery Fund?', '¿Cuál es el propósito del Fondo de Recuperación de Bienes Raíces de Texas?', '["To compensate consumers harmed by licensee misconduct", "To fund TREC operations", "To provide loans to new agents", "To insure property transactions"]', '["Compensar a consumidores perjudicados por mala conducta de licenciatarios", "Financiar operaciones de TREC", "Proporcionar préstamos a nuevos agentes", "Asegurar transacciones de propiedades"]', 0, 'The Recovery Fund compensates consumers who have been harmed by the fraudulent or dishonest acts of a licensed broker or sales agent.', 'El Fondo de Recuperación compensa a los consumidores que han sido perjudicados por actos fraudulentos o deshonestos de un corredor o agente de ventas licenciado.', true, '2026-01-14 22:36:12.970852', '2026-01-14 22:36:12.970852') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('11102e87-1742-4323-978b-8c9cd4fc6cb4', 'real_estate', NULL, 'What is redlining?', '¿Qué es el redlining?', '["Refusing to provide services to certain geographic areas based on demographics", "Drawing property boundaries", "Creating marketing materials", "Setting interest rates"]', '["Negarse a proporcionar servicios a ciertas áreas geográficas basándose en demografía", "Dibujar límites de propiedades", "Crear materiales de marketing", "Establecer tasas de interés"]', 0, 'Redlining is the illegal practice of refusing to provide services in certain areas based on the racial or ethnic composition of those areas.', 'El redlining es la práctica ilegal de negarse a proporcionar servicios en ciertas áreas basándose en la composición racial o étnica de esas áreas.', true, '2026-01-14 22:36:13.269986', '2026-01-14 22:36:13.269986') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('12681757-a0d8-4347-92cf-c615af65cda2', 'real_estate', NULL, 'What is depreciation in real estate?', '¿Qué es la depreciación en bienes raíces?', '["The loss of value due to physical deterioration, functional obsolescence, or external factors", "An increase in value", "The mortgage balance", "Property taxes"]', '["La pérdida de valor debido a deterioro físico, obsolescencia funcional o factores externos", "Un aumento en el valor", "El saldo de la hipoteca", "Impuestos sobre la propiedad"]', 0, 'Depreciation is the loss of property value due to physical wear, outdated features, or external factors.', 'La depreciación es la pérdida del valor de la propiedad debido al desgaste físico, características obsoletas o factores externos.', true, '2026-01-14 22:36:13.189214', '2026-01-14 22:36:13.189214') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('13f0c3cd-4f27-4f1a-8a83-8ffbd5d7f166', 'real_estate', NULL, 'A counteroffer in real estate:', 'Una contraoferta en bienes raíces:', '["Terminates the original offer and creates a new offer", "Accepts the original offer with modifications", "Must be in the same amount as the original", "Is automatically accepted"]', '["Termina la oferta original y crea una nueva oferta", "Acepta la oferta original con modificaciones", "Debe ser por el mismo monto que la original", "Se acepta automáticamente"]', 0, 'A counteroffer terminates the original offer and creates a new offer that the other party may accept, reject, or counter.', 'Una contraoferta termina la oferta original y crea una nueva oferta que la otra parte puede aceptar, rechazar o contraofertar.', true, '2026-01-14 22:36:13.066176', '2026-01-14 22:36:13.066176') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('143d5da6-df77-4574-b93e-7a8df3ca66e1', 'real_estate', NULL, 'Which of the following would be grounds for TREC to deny a license application?', '¿Cuál de los siguientes sería motivo para que TREC niegue una solicitud de licencia?', '["Felony conviction involving fraud", "Having a civil judgment", "Being under 25 years old", "Not owning property"]', '["Condena por delito grave que involucre fraude", "Tener un fallo civil", "Tener menos de 25 años", "No ser propietario de bienes"]', 0, 'TREC may deny a license to an applicant with a felony conviction, particularly one involving fraud, dishonesty, or moral turpitude.', 'TREC puede negar una licencia a un solicitante con una condena por delito grave, particularmente uno que involucre fraude, deshonestidad o torpeza moral.', true, '2026-01-14 22:36:12.961769', '2026-01-14 22:36:12.961769') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('149e3dd7-02ac-4f46-9f92-f6415372cd32', 'real_estate', NULL, 'What is gross rent multiplier (GRM)?', '¿Qué es el multiplicador de alquiler bruto (GRM)?', '["Property price divided by annual gross rental income", "Monthly rent times 12", "Net operating income divided by price", "Cap rate times 100"]', '["Precio de la propiedad dividido por el ingreso de alquiler bruto anual", "Alquiler mensual por 12", "Ingreso operativo neto dividido por precio", "Tasa de capitalización por 100"]', 0, 'GRM is calculated by dividing the property price by the annual gross rental income, used to compare investment properties.', 'El GRM se calcula dividiendo el precio de la propiedad por el ingreso de alquiler bruto anual, usado para comparar propiedades de inversión.', true, '2026-01-14 22:36:13.407258', '2026-01-14 22:36:13.407258') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('15369f5f-bff4-4617-a389-8aba24eb0e14', 'real_estate', NULL, 'Private Mortgage Insurance (PMI) is typically required when:', 'El Seguro Hipotecario Privado (PMI) típicamente se requiere cuando:', '["The down payment is less than 20%", "The buyer has excellent credit", "The loan is from the VA", "The property is commercial"]', '["El pago inicial es menos del 20%", "El comprador tiene excelente crédito", "El préstamo es del VA", "La propiedad es comercial"]', 0, 'PMI is typically required when the buyer''s down payment is less than 20% of the purchase price.', 'El PMI típicamente se requiere cuando el pago inicial del comprador es menos del 20% del precio de compra.', true, '2026-01-14 22:36:13.101596', '2026-01-14 22:36:13.101596') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('17a3fc8e-9ab4-4e73-8548-2b7d964797b9', 'real_estate', NULL, 'What is depreciation in real estate appraisal?', '¿Qué es la depreciación en la tasación de bienes raíces?', '["Loss in property value due to any cause", "Increase in property value", "The cost of repairs", "Property taxes"]', '["Pérdida en el valor de la propiedad debido a cualquier causa", "Aumento en el valor de la propiedad", "El costo de reparaciones", "Impuestos sobre la propiedad"]', 0, 'Depreciation is the loss in value of a property due to physical deterioration, functional obsolescence, or external factors.', 'La depreciación es la pérdida de valor de una propiedad debido al deterioro físico, obsolescencia funcional o factores externos.', true, '2026-01-14 18:28:35.359568', '2026-01-14 18:28:35.359568') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('193949ec-cd27-4687-a3e8-4d7375dc7a10', 'real_estate', NULL, 'What is an ARM in mortgage lending?', '¿Qué es un ARM en préstamos hipotecarios?', '["Adjustable Rate Mortgage", "Annual Rate Mortgage", "Approved Residential Mortgage", "Alternative Rate Method"]', '["Hipoteca de Tasa Ajustable", "Hipoteca de Tasa Anual", "Hipoteca Residencial Aprobada", "Método de Tasa Alternativa"]', 0, 'An ARM (Adjustable Rate Mortgage) has an interest rate that changes periodically based on a benchmark index.', 'Un ARM (Hipoteca de Tasa Ajustable) tiene una tasa de interés que cambia periódicamente basándose en un índice de referencia.', true, '2026-01-14 18:28:35.380573', '2026-01-14 18:28:35.380573') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('194a3cda-37bd-4760-af68-5781b6db9a0a', 'real_estate', NULL, 'In Texas, what type of agency relationship exists when a broker represents both buyer and seller?', 'En Texas, ¿qué tipo de relación de agencia existe cuando un corredor representa tanto al comprador como al vendedor?', '["Intermediary", "Dual agency", "Single agency", "Sub-agency"]', '["Intermediario", "Agencia dual", "Agencia única", "Sub-agencia"]', 0, 'Texas uses the intermediary relationship when a broker represents both parties, requiring written consent from both.', 'Texas usa la relación de intermediario cuando un corredor representa a ambas partes, requiriendo consentimiento escrito de ambos.', true, '2026-01-14 22:36:13.006766', '2026-01-14 22:36:13.006766') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1b2ff0f3-90ef-4153-bcf1-9f294dd618f0', 'real_estate', NULL, 'What is the difference between the primary and secondary mortgage markets?', '¿Cuál es la diferencia entre los mercados hipotecarios primario y secundario?', '["Primary is where loans are originated; secondary is where they are bought and sold", "There is no difference", "Primary is for residential; secondary is for commercial", "Primary is for first mortgages only"]', '["El primario es donde se originan los préstamos; el secundario es donde se compran y venden", "No hay diferencia", "El primario es para residencial; el secundario es para comercial", "El primario es solo para primeras hipotecas"]', 0, 'The primary market is where loans are originated between lenders and borrowers. The secondary market is where loans are bought and sold among investors.', 'El mercado primario es donde se originan los préstamos entre prestamistas y prestatarios. El mercado secundario es donde los préstamos se compran y venden entre inversores.', true, '2026-01-14 18:28:35.400046', '2026-01-14 18:28:35.400046') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1b418ace-8b1a-4432-ba49-e48eeb4bbc61', 'real_estate', NULL, 'What is the most common method of property appraisal for residential properties?', '¿Cuál es el método más común de tasación de propiedad para propiedades residenciales?', '["Sales comparison approach", "Income approach", "Cost approach", "Investment approach"]', '["Enfoque de comparación de ventas", "Enfoque de ingresos", "Enfoque de costos", "Enfoque de inversión"]', 0, 'The sales comparison approach compares the subject property to similar recently sold properties to determine market value.', 'El enfoque de comparación de ventas compara la propiedad sujeta con propiedades similares vendidas recientemente para determinar el valor de mercado.', true, '2026-01-14 18:28:35.356704', '2026-01-14 18:28:35.356704') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1b7f2c63-7576-4be9-90b0-c94537e585a6', 'real_estate', NULL, 'Which properties are exempt from the Texas Seller''s Disclosure requirement?', '¿Qué propiedades están exentas del requisito de Divulgación del Vendedor de Texas?', '["Foreclosures, new construction by a builder, and transfers by court order", "All residential properties", "Properties under $100,000", "Properties over 50 years old"]', '["Ejecuciones hipotecarias, nueva construcción por un constructor y transferencias por orden judicial", "Todas las propiedades residenciales", "Propiedades menores de $100,000", "Propiedades de más de 50 años"]', 0, 'Certain transfers are exempt from disclosure requirements, including foreclosures, new construction, and court-ordered transfers.', 'Ciertas transferencias están exentas de requisitos de divulgación, incluyendo ejecuciones hipotecarias, nueva construcción y transferencias ordenadas por el tribunal.', true, '2026-01-14 22:36:13.218673', '2026-01-14 22:36:13.218673') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1beb2e53-fdee-4cda-9e6c-17f7bc55b0a4', 'real_estate', NULL, 'How many hours of pre-licensing education are required for a Texas sales agent license?', '¿Cuántas horas de educación pre-licencia se requieren para una licencia de agente de ventas en Texas?', '["180 hours", "90 hours", "60 hours", "30 hours"]', '["180 horas", "90 horas", "60 horas", "30 horas"]', 0, 'Texas requires 180 hours of approved pre-licensing education for sales agent applicants.', 'Texas requiere 180 horas de educación pre-licencia aprobada para solicitantes de agente de ventas.', true, '2026-01-14 18:28:35.444609', '2026-01-14 18:28:35.444609') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1c9a8242-8dea-44a7-b421-2f6b10988eed', 'real_estate', NULL, 'Which agency enforces Fair Housing laws?', '¿Qué agencia hace cumplir las leyes de Vivienda Justa?', '["HUD (Department of Housing and Urban Development)", "FBI", "IRS", "SEC"]', '["HUD (Departamento de Vivienda y Desarrollo Urbano)", "FBI", "IRS", "SEC"]', 0, 'The U.S. Department of Housing and Urban Development (HUD) is the primary federal agency enforcing Fair Housing laws.', 'El Departamento de Vivienda y Desarrollo Urbano de EE.UU. (HUD) es la principal agencia federal que hace cumplir las leyes de Vivienda Justa.', true, '2026-01-14 22:36:13.292598', '2026-01-14 22:36:13.292598') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1d3df294-5a07-46b8-ac93-902b144212ff', 'real_estate', NULL, 'What are common buyer closing costs?', '¿Cuáles son los costos de cierre comunes del comprador?', '["Loan origination fees, appraisal, title insurance, and prepaid items", "Real estate commission", "Seller''s moving expenses", "Property repairs"]', '["Cargos de originación del préstamo, tasación, seguro de título y artículos prepagados", "Comisión de bienes raíces", "Gastos de mudanza del vendedor", "Reparaciones de la propiedad"]', 0, 'Buyer closing costs typically include loan fees, appraisal, title insurance, escrow setup, and prepaid items like taxes and insurance.', 'Los costos de cierre del comprador típicamente incluyen cargos del préstamo, tasación, seguro de título, configuración de escrow y artículos prepagados como impuestos y seguro.', true, '2026-01-14 22:36:13.324966', '2026-01-14 22:36:13.324966') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1ed3e747-f0fc-4712-aad8-43c0fa0fdbc8', 'real_estate', NULL, 'What is a quitclaim deed used for?', '¿Para qué se usa una escritura de renuncia?', '["To transfer whatever interest the grantor has without warranties", "To provide full warranty of title", "To create a mortgage", "To establish a lease"]', '["Para transferir cualquier interés que el otorgante tenga sin garantías", "Para proporcionar garantía completa del título", "Para crear una hipoteca", "Para establecer un arrendamiento"]', 0, 'A quitclaim deed transfers whatever interest the grantor has (if any) without making any warranties about the title.', 'Una escritura de renuncia transfiere cualquier interés que el otorgante tenga (si lo hay) sin hacer garantías sobre el título.', true, '2026-01-14 18:28:35.560155', '2026-01-14 18:28:35.560155') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('23d2c3e4-e03f-4292-abf1-0e8237abe592', 'real_estate', NULL, 'The amendment versus addendum: An addendum is used to:', 'La enmienda versus el anexo: Un anexo se usa para:', '["Add terms to a contract before execution", "Change terms after the contract is executed", "Cancel a contract", "Extend the closing date"]', '["Agregar términos a un contrato antes de la ejecución", "Cambiar términos después de que el contrato se ejecuta", "Cancelar un contrato", "Extender la fecha de cierre"]', 0, 'An addendum adds terms to a contract before execution, while an amendment modifies terms after execution.', 'Un anexo agrega términos a un contrato antes de la ejecución, mientras que una enmienda modifica términos después de la ejecución.', true, '2026-01-14 22:36:13.07184', '2026-01-14 22:36:13.07184') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2470858e-3383-4cc1-92cb-ae2f3d4ac804', 'real_estate', NULL, 'What is zoning?', '¿Qué es la zonificación?', '["Government regulation of land use within designated areas", "Property tax assessment", "Building inspection", "Title examination"]', '["Regulación gubernamental del uso de terreno dentro de áreas designadas", "Evaluación de impuestos sobre la propiedad", "Inspección de edificios", "Examen de título"]', 0, 'Zoning is a government regulation that divides land into zones and controls how property in each zone may be used.', 'La zonificación es una regulación gubernamental que divide el terreno en zonas y controla cómo puede usarse la propiedad en cada zona.', true, '2026-01-14 22:36:13.345212', '2026-01-14 22:36:13.345212') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2495282c-4985-4b7d-a970-fddcc9ce44c9', 'real_estate', NULL, 'What is a mortgage assumption?', '¿Qué es una asunción de hipoteca?', '["When a buyer takes over the seller''s existing mortgage", "A new loan application", "A loan denial", "A refinancing option"]', '["Cuando un comprador toma el control de la hipoteca existente del vendedor", "Una nueva solicitud de préstamo", "Una denegación de préstamo", "Una opción de refinanciamiento"]', 0, 'A mortgage assumption occurs when a buyer agrees to take over the seller''s existing mortgage under its current terms.', 'Una asunción de hipoteca ocurre cuando un comprador acepta tomar el control de la hipoteca existente del vendedor bajo sus términos actuales.', true, '2026-01-14 22:36:13.129282', '2026-01-14 22:36:13.129282') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('26f3b193-5711-452c-916e-df3e255d4003', 'real_estate', NULL, 'What is the difference between a listing agent and a buyer''s agent?', '¿Cuál es la diferencia entre un agente de listado y un agente del comprador?', '["There is no difference", "A listing agent represents the seller, while a buyer''s agent represents the buyer", "A listing agent only works with commercial properties", "A buyer''s agent is not licensed"]', '["No hay diferencia", "Un agente de listado representa al vendedor, mientras que un agente del comprador representa al comprador", "Un agente de listado solo trabaja con propiedades comerciales", "Un agente del comprador no tiene licencia"]', 1, 'A listing agent represents the seller''s interests, while a buyer''s agent represents the buyer''s interests in a real estate transaction.', 'Un agente de listado representa los intereses del vendedor, mientras que un agente del comprador representa los intereses del comprador en una transacción inmobiliaria.', true, '2026-01-14 18:28:35.34236', '2026-01-14 18:28:35.34236') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('276a590e-31e4-45bb-af41-d4b560a9ecd8', 'real_estate', NULL, 'Which of the following is considered real property?', '¿Cuál de los siguientes se considera propiedad inmueble?', '["A built-in dishwasher", "A portable air conditioner", "Furniture", "A car"]', '["Un lavavajillas empotrado", "Un aire acondicionado portátil", "Muebles", "Un carro"]', 0, 'A built-in dishwasher is a fixture attached to the property and is considered real property.', 'Un lavavajillas empotrado es un accesorio adjunto a la propiedad y se considera propiedad inmueble.', true, '2026-01-14 18:28:35.299479', '2026-01-14 18:28:35.299479') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2a797d8b-47ea-41f6-a2ba-ca2bb3c8f413', 'real_estate', NULL, 'What is redlining?', '¿Qué es el redlining?', '["An illegal practice of refusing services based on geographic area, often linked to race", "A type of mortgage", "A zoning practice", "A legal marketing strategy"]', '["Una práctica ilegal de rechazar servicios basándose en área geográfica, a menudo vinculada a raza", "Un tipo de hipoteca", "Una práctica de zonificación", "Una estrategia legal de mercadeo"]', 0, 'Redlining is the discriminatory practice of refusing loans or services to residents of certain areas based on race or ethnicity.', 'El redlining es la práctica discriminatoria de rechazar préstamos o servicios a residentes de ciertas áreas basándose en raza o etnia.', true, '2026-01-14 18:28:35.532008', '2026-01-14 18:28:35.532008') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2bfbf184-ae3b-4088-aba2-8bc398bd7c3f', 'real_estate', NULL, 'TREC promulgated contract forms are:', 'Los formularios de contrato promulgados por TREC son:', '["Required for use by license holders in most transactions", "Optional suggestions", "Only for commercial transactions", "Created by the Texas Bar Association"]', '["Requeridos para uso de titulares de licencia en la mayoría de transacciones", "Sugerencias opcionales", "Solo para transacciones comerciales", "Creados por el Colegio de Abogados de Texas"]', 0, 'License holders are required to use TREC promulgated contract forms for most residential transactions in Texas.', 'Los titulares de licencia están obligados a usar formularios de contrato promulgados por TREC para la mayoría de transacciones residenciales en Texas.', true, '2026-01-14 22:36:12.997869', '2026-01-14 22:36:12.997869') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2c636912-2def-46b7-92d9-d67284ac3a44', 'real_estate', NULL, 'The Americans with Disabilities Act (ADA) requires:', 'La Ley de Estadounidenses con Discapacidades (ADA) requiere:', '["Reasonable accommodations for persons with disabilities in public accommodations", "All homes to have elevators", "All properties to be wheelchair accessible", "Special parking only"]', '["Acomodaciones razonables para personas con discapacidades en lugares públicos", "Que todas las casas tengan elevadores", "Que todas las propiedades sean accesibles para sillas de ruedas", "Solo estacionamiento especial"]', 0, 'The ADA requires reasonable accommodations and accessibility modifications in places of public accommodation.', 'La ADA requiere acomodaciones razonables y modificaciones de accesibilidad en lugares de acomodación pública.', true, '2026-01-14 22:36:13.280043', '2026-01-14 22:36:13.280043') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2dc3621a-dc34-4d23-94b3-32799e21b853', 'real_estate', NULL, 'What is a Multiple Listing Service (MLS)?', '¿Qué es un Servicio de Listado Múltiple (MLS)?', '["A database of properties for sale shared among real estate professionals", "A government agency", "A type of mortgage", "A title company"]', '["Una base de datos de propiedades en venta compartida entre profesionales inmobiliarios", "Una agencia gubernamental", "Un tipo de hipoteca", "Una compañía de títulos"]', 0, 'The MLS is a database where real estate agents share information about properties for sale to facilitate cooperation among brokers.', 'El MLS es una base de datos donde los agentes inmobiliarios comparten información sobre propiedades en venta para facilitar la cooperación entre corredores.', true, '2026-01-14 18:28:35.501109', '2026-01-14 18:28:35.501109') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2ec3dff4-5083-498f-9ed2-59ac9dfcc485', 'real_estate', NULL, 'What is title insurance?', '¿Qué es el seguro de título?', '["Insurance protecting against defects in property title", "Homeowner''s insurance", "Flood insurance", "Mortgage insurance"]', '["Seguro que protege contra defectos en el título de propiedad", "Seguro de propietario", "Seguro contra inundaciones", "Seguro hipotecario"]', 0, 'Title insurance protects lenders and buyers against financial loss from defects in a property''s title, including liens and encumbrances.', 'El seguro de título protege a prestamistas y compradores contra pérdidas financieras por defectos en el título de una propiedad, incluyendo gravámenes y cargas.', true, '2026-01-14 18:28:35.345486', '2026-01-14 18:28:35.345486') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2f27051c-35d6-4d9a-babe-ef8ea5764a5b', 'real_estate', NULL, 'What is the purpose of a homeowners association (HOA)?', '¿Cuál es el propósito de una asociación de propietarios (HOA)?', '["To manage common areas and enforce community rules and regulations", "To sell properties", "To provide mortgages", "To conduct appraisals"]', '["Administrar áreas comunes y hacer cumplir reglas y regulaciones de la comunidad", "Vender propiedades", "Proporcionar hipotecas", "Realizar tasaciones"]', 0, 'An HOA manages common areas, enforces deed restrictions, and maintains community standards in a subdivision or development.', 'Una HOA administra áreas comunes, hace cumplir restricciones de escritura y mantiene estándares comunitarios en una subdivisión o desarrollo.', true, '2026-01-14 22:36:58.987756', '2026-01-14 22:36:58.987756') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2f75356e-6100-494a-81d3-276db84a106b', 'real_estate', NULL, 'Who typically attends a real estate closing in Texas?', '¿Quién típicamente asiste a un cierre de bienes raíces en Texas?', '["Buyer, seller, real estate agents, title company representative, and lender representative", "Only the buyer", "Only the seller", "Only the agents"]', '["Comprador, vendedor, agentes de bienes raíces, representante de la compañía de títulos y representante del prestamista", "Solo el comprador", "Solo el vendedor", "Solo los agentes"]', 0, 'Texas closings typically involve the buyer, seller, their agents, a title company representative, and often a lender representative.', 'Los cierres en Texas típicamente involucran al comprador, vendedor, sus agentes, un representante de la compañía de títulos, y a menudo un representante del prestamista.', true, '2026-01-14 22:36:13.300448', '2026-01-14 22:36:13.300448') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2f8918f0-76d1-4898-a443-46171bfc3424', 'real_estate', NULL, 'What does ''time is of the essence'' mean in a contract?', '¿Qué significa ''el tiempo es esencial'' en un contrato?', '["All deadlines must be strictly adhered to", "The contract has no deadlines", "Time limits are flexible", "The contract is temporary"]', '["Todos los plazos deben cumplirse estrictamente", "El contrato no tiene plazos", "Los límites de tiempo son flexibles", "El contrato es temporal"]', 0, 'When ''time is of the essence,'' all dates and deadlines in the contract are strict, and failure to meet them is a breach.', 'Cuando ''el tiempo es esencial,'' todas las fechas y plazos en el contrato son estrictos, y no cumplirlos es un incumplimiento.', true, '2026-01-14 18:28:35.426407', '2026-01-14 18:28:35.426407') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('315b385d-1305-4c47-aa53-efa97ec492a3', 'real_estate', NULL, 'What is a building permit?', '¿Qué es un permiso de construcción?', '["Official permission from the local government to construct or modify a building", "A zoning change", "A deed restriction", "A title policy"]', '["Permiso oficial del gobierno local para construir o modificar un edificio", "Un cambio de zonificación", "Una restricción de escritura", "Una póliza de título"]', 0, 'A building permit is authorization from local government allowing construction or renovation to proceed.', 'Un permiso de construcción es una autorización del gobierno local que permite que la construcción o renovación proceda.', true, '2026-01-14 22:36:13.365416', '2026-01-14 22:36:13.365416') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('31dfddd7-3536-4297-ba86-3cef030d357a', 'real_estate', NULL, 'What is the purpose of a survey in real estate?', '¿Cuál es el propósito de un levantamiento topográfico en bienes raíces?', '["To determine property boundaries and identify encroachments", "To determine property value", "To inspect the home''s condition", "To test for radon"]', '["Determinar los límites de la propiedad e identificar invasiones", "Determinar el valor de la propiedad", "Inspeccionar la condición de la casa", "Probar para radón"]', 0, 'A survey identifies property boundaries, improvements, easements, and any encroachments on the property.', 'Un levantamiento topográfico identifica los límites de la propiedad, mejoras, servidumbres y cualquier invasión en la propiedad.', true, '2026-01-14 22:36:13.235889', '2026-01-14 22:36:13.235889') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('31faf6b4-a95a-451b-834d-1c0c6a1ef294', 'real_estate', NULL, 'What is a security deposit?', '¿Qué es un depósito de seguridad?', '["Money paid by tenant to cover potential damages or unpaid rent", "The first month''s rent", "The commission", "The option fee"]', '["Dinero pagado por el inquilino para cubrir daños potenciales o alquiler impago", "El primer mes de alquiler", "La comisión", "La tarifa de opción"]', 0, 'A security deposit is money paid by a tenant to protect the landlord against property damage or unpaid rent.', 'Un depósito de seguridad es dinero pagado por un inquilino para proteger al arrendador contra daños a la propiedad o alquiler impago.', true, '2026-01-14 22:36:13.391916', '2026-01-14 22:36:13.391916') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('327fb379-cceb-41b8-b5ae-f597bc1eeaa2', 'real_estate', NULL, 'What is the purpose of a loan estimate?', '¿Cuál es el propósito de un estimado de préstamo?', '["To provide borrowers with estimated loan costs and terms within 3 days of application", "To approve the loan", "To deny the loan", "To transfer the loan"]', '["Proporcionar a los prestatarios costos y términos estimados del préstamo dentro de 3 días de la solicitud", "Aprobar el préstamo", "Denegar el préstamo", "Transferir el préstamo"]', 0, 'A Loan Estimate must be provided within 3 business days of a mortgage application, showing estimated costs and terms.', 'Un Estimado de Préstamo debe proporcionarse dentro de 3 días hábiles de una solicitud de hipoteca, mostrando costos y términos estimados.', true, '2026-01-14 22:36:13.132749', '2026-01-14 22:36:13.132749') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('32d1e4bc-35b1-499a-8ba2-5d6ea784d15b', 'real_estate', NULL, 'What is fiduciary duty in real estate?', '¿Qué es el deber fiduciario en bienes raíces?', '["A legal obligation to act in the client''s best interest", "A marketing strategy", "A type of insurance", "A closing procedure"]', '["Una obligación legal de actuar en el mejor interés del cliente", "Una estrategia de mercadeo", "Un tipo de seguro", "Un procedimiento de cierre"]', 0, 'Fiduciary duty requires agents to act with loyalty, confidentiality, disclosure, obedience, and reasonable care for their clients.', 'El deber fiduciario requiere que los agentes actúen con lealtad, confidencialidad, divulgación, obediencia y cuidado razonable para sus clientes.', true, '2026-01-14 18:28:35.429741', '2026-01-14 18:28:35.429741') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('357d0dfa-d6e9-48c9-83da-63ac76b8e8a4', 'real_estate', NULL, 'The Fair Housing Act prohibits discrimination based on:', 'La Ley de Vivienda Justa prohíbe la discriminación basada en:', '["Race, color, religion, national origin, sex, familial status, and disability", "Income level", "Credit score", "Employment history"]', '["Raza, color, religión, origen nacional, sexo, estado familiar y discapacidad", "Nivel de ingresos", "Puntaje de crédito", "Historial de empleo"]', 0, 'The Fair Housing Act protects seven classes: race, color, religion, national origin, sex, familial status, and disability.', 'La Ley de Vivienda Justa protege siete clases: raza, color, religión, origen nacional, sexo, estado familiar y discapacidad.', true, '2026-01-14 22:36:13.256862', '2026-01-14 22:36:13.256862') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('35fb9b43-5d1c-4521-b80d-8403131df6cc', 'real_estate', NULL, 'What is the role of a title company?', '¿Cuál es el rol de una compañía de títulos?', '["To research title history and provide title insurance", "To approve mortgages", "To inspect properties", "To set property values"]', '["Investigar el historial del título y proporcionar seguro de título", "Aprobar hipotecas", "Inspeccionar propiedades", "Establecer valores de propiedad"]', 0, 'A title company researches property ownership history, ensures clear title, and provides title insurance.', 'Una compañía de títulos investiga el historial de propiedad, asegura un título claro y proporciona seguro de título.', true, '2026-01-14 18:28:35.484148', '2026-01-14 18:28:35.484148') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('37bdca3b-39d1-49b6-ab64-0375dbf000e8', 'real_estate', NULL, 'What is an HOA?', '¿Qué es una HOA?', '["Homeowners Association that manages shared property and enforces rules", "A type of mortgage", "A government agency", "A title company"]', '["Asociación de Propietarios que administra propiedades compartidas y hace cumplir reglas", "Un tipo de hipoteca", "Una agencia gubernamental", "Una compañía de títulos"]', 0, 'An HOA is an organization in a subdivision or condominium that makes and enforces rules and maintains common areas.', 'Una HOA es una organización en una subdivisión o condominio que hace y hace cumplir reglas y mantiene áreas comunes.', true, '2026-01-14 18:28:35.525091', '2026-01-14 18:28:35.525091') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('384a2306-185e-4ae8-82f5-19156a2a22b0', 'real_estate', NULL, 'What is a reasonable accommodation under Fair Housing?', '¿Qué es una acomodación razonable según la Vivienda Justa?', '["A change in rules, policies, or services to allow a disabled person equal housing opportunity", "A rent reduction", "A security deposit waiver", "A lease termination"]', '["Un cambio en reglas, políticas o servicios para permitir a una persona discapacitada igualdad de oportunidad de vivienda", "Una reducción de alquiler", "Una exención del depósito de seguridad", "Una terminación de arrendamiento"]', 0, 'A reasonable accommodation is a change in rules, policies, or services that enables a person with a disability to have equal housing opportunities.', 'Una acomodación razonable es un cambio en reglas, políticas o servicios que permite a una persona con discapacidad tener igualdad de oportunidades de vivienda.', true, '2026-01-14 22:36:13.284684', '2026-01-14 22:36:13.284684') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('389b8c12-7cef-4323-9dcf-ac54e798ea71', 'real_estate', NULL, 'When may a broker act as an intermediary in Texas?', '¿Cuándo puede un corredor actuar como intermediario en Texas?', '["When both parties give written consent", "At any time without consent", "Only in commercial transactions", "Never, it is prohibited"]', '["Cuando ambas partes dan consentimiento escrito", "En cualquier momento sin consentimiento", "Solo en transacciones comerciales", "Nunca, está prohibido"]', 0, 'A broker may act as an intermediary only if both the buyer and seller consent in writing.', 'Un corredor puede actuar como intermediario solo si tanto el comprador como el vendedor consienten por escrito.', true, '2026-01-14 22:36:13.014505', '2026-01-14 22:36:13.014505') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3d559d3d-ed1d-4191-8748-0f5025017d06', 'real_estate', NULL, 'What type of deed provides the greatest protection to the buyer?', '¿Qué tipo de escritura proporciona la mayor protección al comprador?', '["General warranty deed", "Quitclaim deed", "Special warranty deed", "Bargain and sale deed"]', '["Escritura de garantía general", "Escritura de renuncia", "Escritura de garantía especial", "Escritura de compraventa"]', 0, 'A general warranty deed provides the greatest protection because the grantor guarantees the title against all defects, even those from previous owners.', 'Una escritura de garantía general proporciona la mayor protección porque el otorgante garantiza el título contra todos los defectos, incluso los de propietarios anteriores.', true, '2026-01-14 18:28:35.288011', '2026-01-14 18:28:35.288011') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3dec0bde-4985-423d-bb85-09c84c5c55c7', 'real_estate', NULL, 'What is the primary source of income for a real estate agent?', '¿Cuál es la fuente principal de ingresos para un agente de bienes raíces?', '["Commission on property sales", "Hourly wages", "Monthly salary from TREC", "Government subsidies"]', '["Comisión sobre ventas de propiedades", "Salario por hora", "Salario mensual de TREC", "Subsidios del gobierno"]', 0, 'Real estate agents typically earn income through commissions based on the sale price of properties they help buy or sell.', 'Los agentes de bienes raíces típicamente ganan ingresos a través de comisiones basadas en el precio de venta de las propiedades que ayudan a comprar o vender.', true, '2026-01-14 22:36:58.966785', '2026-01-14 22:36:58.966785') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('40177235-2122-4af0-97a7-11a65367d928', 'real_estate', NULL, 'What is a cap rate in real estate investing?', '¿Qué es la tasa de capitalización en inversión inmobiliaria?', '["Net operating income divided by property value", "The interest rate on a mortgage", "The property tax rate", "The commission rate"]', '["Ingreso neto operativo dividido por el valor de la propiedad", "La tasa de interés de una hipoteca", "La tasa de impuestos sobre la propiedad", "La tasa de comisión"]', 0, 'Capitalization rate (cap rate) measures a property''s potential return, calculated as annual net operating income divided by purchase price.', 'La tasa de capitalización mide el retorno potencial de una propiedad, calculada como ingreso neto operativo anual dividido por el precio de compra.', true, '2026-01-14 18:28:35.518876', '2026-01-14 18:28:35.518876') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('43985e74-62b2-48d8-97dc-1b96f2e5a6e5', 'real_estate', NULL, 'What is foreclosure?', '¿Qué es una ejecución hipotecaria?', '["The legal process by which a lender takes possession of a property due to default", "A type of mortgage", "A home improvement loan", "A property tax assessment"]', '["El proceso legal por el cual un prestamista toma posesión de una propiedad debido a incumplimiento", "Un tipo de hipoteca", "Un préstamo para mejoras del hogar", "Una evaluación de impuestos sobre la propiedad"]', 0, 'Foreclosure is the legal process allowing a lender to recover the balance of a loan by selling the mortgaged property.', 'La ejecución hipotecaria es el proceso legal que permite a un prestamista recuperar el saldo de un préstamo vendiendo la propiedad hipotecada.', true, '2026-01-14 18:28:35.492966', '2026-01-14 18:28:35.492966') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('44141d31-f7de-469d-9bb0-e84f85a05dcb', 'real_estate', NULL, 'What is a conventional loan?', '¿Qué es un préstamo convencional?', '["A loan not insured or guaranteed by a government agency", "A government-backed loan", "A VA loan", "An FHA loan"]', '["Un préstamo no asegurado ni garantizado por una agencia gubernamental", "Un préstamo respaldado por el gobierno", "Un préstamo VA", "Un préstamo FHA"]', 0, 'A conventional loan is made by private lenders without government insurance or guarantees.', 'Un préstamo convencional es hecho por prestamistas privados sin seguro ni garantías del gobierno.', true, '2026-01-14 22:36:13.105127', '2026-01-14 22:36:13.105127') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4499f7d3-a94a-4b8e-9217-72f10f96a54f', 'real_estate', NULL, 'What is a plat?', '¿Qué es un plano de subdivisión?', '["A map showing the division of land into lots", "A deed", "A mortgage document", "An appraisal"]', '["Un mapa que muestra la división del terreno en lotes", "Una escritura", "Un documento hipotecario", "Una tasación"]', 0, 'A plat is a map of a subdivision showing individual lots, streets, easements, and other features.', 'Un plano de subdivisión es un mapa de una subdivisión que muestra lotes individuales, calles, servidumbres y otras características.', true, '2026-01-14 22:36:13.374755', '2026-01-14 22:36:13.374755') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('44f06697-f949-47bd-96dd-a5b64934ec4a', 'real_estate', NULL, 'An exclusive right-to-sell listing means:', 'Un listado de derecho exclusivo de venta significa:', '["The broker earns a commission regardless of who sells the property", "The seller can sell without paying commission", "Multiple brokers can list the property", "No commission is paid"]', '["El corredor gana una comisión independientemente de quién venda la propiedad", "El vendedor puede vender sin pagar comisión", "Múltiples corredores pueden listar la propiedad", "No se paga comisión"]', 0, 'In an exclusive right-to-sell listing, the broker earns commission if the property sells during the listing period, regardless of who procures the buyer.', 'En un listado de derecho exclusivo de venta, el corredor gana comisión si la propiedad se vende durante el período de listado, independientemente de quién consiga al comprador.', true, '2026-01-14 22:36:13.095316', '2026-01-14 22:36:13.095316') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4acd1e91-786a-4fcd-9808-b91e9b257b24', 'real_estate', NULL, 'What is the purpose of RESPA?', '¿Cuál es el propósito de RESPA?', '["To protect consumers from abusive practices in the real estate settlement process", "To set interest rates", "To regulate property taxes", "To license real estate agents"]', '["Proteger a los consumidores de prácticas abusivas en el proceso de cierre de bienes raíces", "Establecer tasas de interés", "Regular impuestos sobre la propiedad", "Licenciar agentes inmobiliarios"]', 0, 'RESPA (Real Estate Settlement Procedures Act) protects consumers by requiring disclosures and prohibiting kickbacks.', 'RESPA (Ley de Procedimientos de Liquidación de Bienes Raíces) protege a los consumidores requiriendo divulgaciones y prohibiendo sobornos.', true, '2026-01-14 18:28:35.391313', '2026-01-14 18:28:35.391313') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4b8f3559-2184-438a-a8da-7eb96973d6aa', 'real_estate', NULL, 'A listing agreement in Texas creates what type of agency relationship?', 'Un acuerdo de listado en Texas crea qué tipo de relación de agencia?', '["Seller agency", "Buyer agency", "Dual agency", "No agency"]', '["Agencia del vendedor", "Agencia del comprador", "Agencia dual", "Sin agencia"]', 0, 'A listing agreement creates an agency relationship where the broker represents the seller''s interests.', 'Un acuerdo de listado crea una relación de agencia donde el corredor representa los intereses del vendedor.', true, '2026-01-14 22:36:13.018396', '2026-01-14 22:36:13.018396') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4c165417-bce1-46f6-be43-c7b0939fef85', 'real_estate', NULL, 'In Texas, who holds the earnest money deposit?', 'En Texas, ¿quién retiene el depósito de garantía?', '["The title company or broker as escrow agent", "The buyer", "The seller", "TREC"]', '["La compañía de títulos o corredor como agente de escrow", "El comprador", "El vendedor", "TREC"]', 0, 'In Texas, the earnest money is typically held by the title company or the listing broker acting as escrow agent.', 'En Texas, el depósito de garantía típicamente lo retiene la compañía de títulos o el corredor de listado actuando como agente de escrow.', true, '2026-01-14 18:28:35.448705', '2026-01-14 18:28:35.448705') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4d57491c-8f35-46fd-904b-08d5a7eec764', 'real_estate', NULL, 'What is a month-to-month tenancy?', '¿Qué es una tenencia de mes a mes?', '["A periodic tenancy that automatically renews each month until terminated", "A one-month lease", "A commercial lease only", "A sublease"]', '["Una tenencia periódica que se renueva automáticamente cada mes hasta terminarla", "Un arrendamiento de un mes", "Solo un arrendamiento comercial", "Un subarrendamiento"]', 0, 'A month-to-month tenancy is a periodic tenancy that renews automatically each month until properly terminated.', 'Una tenencia de mes a mes es una tenencia periódica que se renueva automáticamente cada mes hasta que se termine apropiadamente.', true, '2026-01-14 22:36:13.432066', '2026-01-14 22:36:13.432066') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4f4ee498-311c-40b9-83c6-dcebd57f6c36', 'real_estate', NULL, 'What is the Closing Disclosure?', '¿Qué es la Divulgación de Cierre?', '["A document showing final loan terms and closing costs, provided 3 days before closing", "The deed to the property", "The appraisal report", "The inspection report"]', '["Un documento que muestra los términos finales del préstamo y costos de cierre, proporcionado 3 días antes del cierre", "La escritura de la propiedad", "El informe de tasación", "El informe de inspección"]', 0, 'The Closing Disclosure must be provided at least 3 business days before closing, showing final loan terms and closing costs.', 'La Divulgación de Cierre debe proporcionarse al menos 3 días hábiles antes del cierre, mostrando los términos finales del préstamo y costos de cierre.', true, '2026-01-14 22:36:13.137075', '2026-01-14 22:36:13.137075') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4f98d375-44f3-4202-9f48-ac5aad689ec1', 'real_estate', NULL, 'What is a real estate broker?', '¿Qué es un corredor de bienes raíces?', '["A licensed professional who can own a brokerage and supervise agents", "The same as a sales agent", "A property inspector", "A mortgage lender"]', '["Un profesional licenciado que puede poseer un corretaje y supervisar agentes", "Lo mismo que un agente de ventas", "Un inspector de propiedades", "Un prestamista hipotecario"]', 0, 'A broker has additional education and licensing that allows them to operate independently and supervise sales agents.', 'Un corredor tiene educación y licencia adicionales que le permiten operar independientemente y supervisar agentes de ventas.', true, '2026-01-14 18:28:35.498652', '2026-01-14 18:28:35.498652') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('503d26bb-3288-4659-a6ea-13f20b7d8cf2', 'real_estate', NULL, 'When does ownership legally transfer in Texas?', '¿Cuándo se transfiere legalmente la propiedad en Texas?', '["When the deed is delivered and accepted", "When the contract is signed", "When the money changes hands", "When the keys are handed over"]', '["Cuando la escritura se entrega y acepta", "Cuando el contrato se firma", "Cuando el dinero cambia de manos", "Cuando se entregan las llaves"]', 0, 'Ownership legally transfers when the deed is delivered to and accepted by the buyer.', 'La propiedad se transfiere legalmente cuando la escritura se entrega y es aceptada por el comprador.', true, '2026-01-14 22:36:13.318436', '2026-01-14 22:36:13.318436') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('525ec678-5b4d-42fa-919c-72dfc5c18ca2', 'real_estate', NULL, 'What are deed restrictions?', '¿Qué son las restricciones de escritura?', '["Private limitations placed on property use by developers or previous owners", "Government zoning laws", "Building codes", "Tax assessments"]', '["Limitaciones privadas sobre el uso de la propiedad por desarrolladores o propietarios anteriores", "Leyes de zonificación del gobierno", "Códigos de construcción", "Evaluaciones fiscales"]', 0, 'Deed restrictions are private agreements that limit how property can be used, often imposed by developers.', 'Las restricciones de escritura son acuerdos privados que limitan cómo puede usarse la propiedad, a menudo impuestas por desarrolladores.', true, '2026-01-14 22:36:13.359343', '2026-01-14 22:36:13.359343') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('52665f0d-e7e6-4d78-a1fd-83e1b2beb498', 'real_estate', NULL, 'What is the option period in Texas real estate?', '¿Qué es el período de opción en bienes raíces de Texas?', '["A negotiated time when the buyer can terminate the contract for any reason", "The closing period", "The loan approval period", "The inspection period only"]', '["Un tiempo negociado cuando el comprador puede terminar el contrato por cualquier razón", "El período de cierre", "El período de aprobación del préstamo", "Solo el período de inspección"]', 0, 'The option period in Texas gives buyers the unrestricted right to terminate the contract for any reason, in exchange for an option fee.', 'El período de opción en Texas da a los compradores el derecho irrestricto de terminar el contrato por cualquier razón, a cambio de una tarifa de opción.', true, '2026-01-14 18:28:35.556806', '2026-01-14 18:28:35.556806') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('55299d44-ff98-4579-991e-3f2a20b559f1', 'real_estate', NULL, 'What is the difference between zoning and deed restrictions?', '¿Cuál es la diferencia entre zonificación y restricciones de escritura?', '["Zoning is public law; deed restrictions are private agreements", "They are the same thing", "Deed restrictions are more powerful", "Zoning is optional"]', '["La zonificación es ley pública; las restricciones de escritura son acuerdos privados", "Son lo mismo", "Las restricciones de escritura son más poderosas", "La zonificación es opcional"]', 0, 'Zoning is government regulation while deed restrictions are private contractual limitations, though both may apply.', 'La zonificación es regulación gubernamental mientras que las restricciones de escritura son limitaciones contractuales privadas, aunque ambas pueden aplicar.', true, '2026-01-14 22:36:13.361991', '2026-01-14 22:36:13.361991') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('55f3b1bb-6dcc-492b-9ef7-9f3fcf0d1b8b', 'real_estate', NULL, 'What is a mechanic''s lien?', '¿Qué es un gravamen de mecánico?', '["A claim by contractors or suppliers for unpaid work or materials", "A type of mortgage", "A government tax lien", "An insurance policy"]', '["Un reclamo por contratistas o proveedores por trabajo o materiales no pagados", "Un tipo de hipoteca", "Un gravamen fiscal del gobierno", "Una póliza de seguro"]', 0, 'A mechanic''s lien is a security interest in the property filed by contractors, subcontractors, or suppliers who provided labor or materials.', 'Un gravamen de mecánico es un interés de seguridad en la propiedad presentado por contratistas, subcontratistas o proveedores que proporcionaron mano de obra o materiales.', true, '2026-01-14 18:28:35.351935', '2026-01-14 18:28:35.351935') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5aa84d3b-5711-47e4-bbbc-2e1624d71c51', 'real_estate', NULL, 'What is PMI?', '¿Qué es PMI?', '["Private Mortgage Insurance", "Property Management Insurance", "Professional Mortgage Index", "Primary Market Interest"]', '["Seguro Hipotecario Privado", "Seguro de Administración de Propiedades", "Índice Hipotecario Profesional", "Interés del Mercado Primario"]', 0, 'PMI (Private Mortgage Insurance) protects the lender if the borrower defaults, typically required when down payment is less than 20%.', 'PMI (Seguro Hipotecario Privado) protege al prestamista si el prestatario incumple, típicamente requerido cuando el pago inicial es menos del 20%.', true, '2026-01-14 18:28:35.376761', '2026-01-14 18:28:35.376761') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5bdd5bd0-ce24-4053-913b-e3194ac4d0cb', 'real_estate', NULL, 'What is a contingency clause in a real estate contract?', '¿Qué es una cláusula de contingencia en un contrato inmobiliario?', '["A condition that must be met for the contract to be binding", "A penalty clause", "A commission agreement", "An escrow instruction"]', '["Una condición que debe cumplirse para que el contrato sea vinculante", "Una cláusula de penalidad", "Un acuerdo de comisión", "Una instrucción de escrow"]', 0, 'A contingency is a condition that must be satisfied before the contract becomes fully binding, such as inspection or financing approval.', 'Una contingencia es una condición que debe cumplirse antes de que el contrato sea completamente vinculante, como inspección o aprobación de financiamiento.', true, '2026-01-14 18:28:35.418183', '2026-01-14 18:28:35.418183') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5c69581d-a01f-485c-9db4-ab5c382191ef', 'real_estate', NULL, 'What happens if a buyer defaults on a purchase contract?', '¿Qué sucede si un comprador incumple un contrato de compra?', '["The seller may retain the earnest money as damages", "Nothing happens", "The buyer gets a refund", "The property is transferred automatically"]', '["El vendedor puede retener el depósito de garantía como daños", "Nada sucede", "El comprador obtiene un reembolso", "La propiedad se transfiere automáticamente"]', 0, 'If a buyer defaults without a valid contingency, the seller typically retains the earnest money as liquidated damages.', 'Si un comprador incumple sin una contingencia válida, el vendedor típicamente retiene el depósito de garantía como daños liquidados.', true, '2026-01-14 18:28:35.414725', '2026-01-14 18:28:35.414725') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5ce0279b-0b73-4a6f-bbbb-e6c771d6d636', 'real_estate', NULL, 'What is a variance in zoning?', '¿Qué es una varianza en zonificación?', '["Permission to deviate from zoning requirements", "A change in property taxes", "A type of mortgage", "A title defect"]', '["Permiso para desviarse de los requisitos de zonificación", "Un cambio en los impuestos sobre la propiedad", "Un tipo de hipoteca", "Un defecto de título"]', 0, 'A variance is an exception granted to a property owner allowing a use that differs from current zoning regulations.', 'Una varianza es una excepción otorgada a un propietario que permite un uso diferente de las regulaciones de zonificación actuales.', true, '2026-01-14 18:28:35.473881', '2026-01-14 18:28:35.473881') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6233697b-4cb8-410e-be15-db7e60cce5e3', 'real_estate', NULL, 'What does ''escrow'' mean in a real estate transaction?', '¿Qué significa ''escrow'' en una transacción inmobiliaria?', '["A type of property insurance", "A neutral third party holding funds until conditions are met", "A real estate agent''s commission", "The down payment on a property"]', '["Un tipo de seguro de propiedad", "Un tercero neutral que retiene fondos hasta que se cumplan las condiciones", "La comisión de un agente inmobiliario", "El pago inicial de una propiedad"]', 1, 'Escrow is a financial arrangement where a third party holds and regulates payment of funds until all conditions of a transaction are met.', 'El escrow es un acuerdo financiero donde un tercero retiene y regula el pago de fondos hasta que se cumplan todas las condiciones de una transacción.', true, '2026-01-14 18:28:35.324998', '2026-01-14 18:28:35.324998') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('63924a58-f077-43a4-8b52-ea2ec1024e44', 'real_estate', NULL, 'What are the essential elements of a valid real estate contract?', '¿Cuáles son los elementos esenciales de un contrato de bienes raíces válido?', '["Competent parties, offer and acceptance, consideration, legal purpose, and written form", "Only a signature", "Verbal agreement only", "Just the price agreed upon"]', '["Partes competentes, oferta y aceptación, contraprestación, propósito legal y forma escrita", "Solo una firma", "Solo acuerdo verbal", "Solo el precio acordado"]', 0, 'A valid real estate contract requires competent parties, mutual agreement (offer and acceptance), consideration, legal purpose, and written form per the Statute of Frauds.', 'Un contrato de bienes raíces válido requiere partes competentes, acuerdo mutuo (oferta y aceptación), contraprestación, propósito legal y forma escrita según el Estatuto de Fraudes.', true, '2026-01-14 22:36:13.043868', '2026-01-14 22:36:13.043868') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('63af280e-0ddc-4013-8e09-493c809029f7', 'real_estate', NULL, 'What is radon?', '¿Qué es el radón?', '["A naturally occurring radioactive gas that can accumulate in buildings", "A type of mold", "A building material", "A pesticide"]', '["Un gas radiactivo de origen natural que puede acumularse en edificios", "Un tipo de moho", "Un material de construcción", "Un pesticida"]', 0, 'Radon is a colorless, odorless radioactive gas that can seep into buildings from the ground and pose health risks.', 'El radón es un gas radiactivo incoloro e inodoro que puede filtrarse en edificios desde el suelo y representar riesgos para la salud.', true, '2026-01-14 22:36:13.231058', '2026-01-14 22:36:13.231058') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('63cff12d-627f-4d8d-8a4b-dd1bd908ce27', 'real_estate', NULL, 'What is a deed of trust?', '¿Qué es una escritura de fideicomiso?', '["A security instrument used instead of a mortgage in Texas", "A warranty deed", "A quitclaim deed", "A title certificate"]', '["Un instrumento de seguridad utilizado en lugar de una hipoteca en Texas", "Una escritura de garantía", "Una escritura de renuncia", "Un certificado de título"]', 0, 'A deed of trust is used in Texas instead of a mortgage, involving three parties: borrower, lender, and trustee.', 'Una escritura de fideicomiso se usa en Texas en lugar de una hipoteca, involucrando tres partes: prestatario, prestamista y fideicomisario.', true, '2026-01-14 18:28:35.481224', '2026-01-14 18:28:35.481224') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('649712db-6e6e-4ec5-99da-8ccd83cc5ca4', 'real_estate', NULL, 'What is earnest money?', '¿Qué es el depósito de garantía?', '["A deposit showing good faith intention to complete a transaction", "The down payment", "The closing costs", "The commission"]', '["Un depósito que muestra intención de buena fe para completar una transacción", "El pago inicial", "Los costos de cierre", "La comisión"]', 0, 'Earnest money is a deposit made by a buyer to demonstrate their serious intent to purchase the property.', 'El depósito de garantía es un depósito hecho por un comprador para demostrar su intención seria de comprar la propiedad.', true, '2026-01-14 18:28:35.410611', '2026-01-14 18:28:35.410611') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('64c38286-1d71-4c18-a244-8f8acb5c1a15', 'real_estate', NULL, 'What is external obsolescence?', '¿Qué es la obsolescencia externa?', '["A loss of value due to factors outside the property", "Outdated appliances", "Physical deterioration", "Poor maintenance"]', '["Una pérdida de valor debido a factores fuera de la propiedad", "Electrodomésticos obsoletos", "Deterioro físico", "Mal mantenimiento"]', 0, 'External obsolescence is the loss of value caused by factors outside the property, such as neighborhood decline or economic conditions.', 'La obsolescencia externa es la pérdida de valor causada por factores fuera de la propiedad, como el deterioro del vecindario o condiciones económicas.', true, '2026-01-14 22:36:13.201518', '2026-01-14 22:36:13.201518') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('65e13b97-9acd-4392-bf60-e264eb3c03fd', 'real_estate', NULL, 'What is prorating in real estate?', '¿Qué es el prorrateo en bienes raíces?', '["Dividing expenses proportionally between buyer and seller at closing", "Setting the selling price", "Calculating the mortgage payment", "Determining the tax assessment"]', '["Dividir gastos proporcionalmente entre comprador y vendedor en el cierre", "Establecer el precio de venta", "Calcular el pago de la hipoteca", "Determinar la evaluación fiscal"]', 0, 'Prorating is the division of certain costs like taxes and HOA fees between buyer and seller based on the closing date.', 'El prorrateo es la división de ciertos costos como impuestos y cuotas de HOA entre comprador y vendedor basándose en la fecha de cierre.', true, '2026-01-14 18:28:35.544365', '2026-01-14 18:28:35.544365') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('668077bd-7bb8-4547-864a-8af3f576101c', 'real_estate', NULL, 'What must be disclosed about lead-based paint?', '¿Qué debe divulgarse sobre la pintura a base de plomo?', '["Known presence of lead-based paint in homes built before 1978", "All paint colors used", "The brand of paint", "Nothing is required"]', '["Presencia conocida de pintura a base de plomo en casas construidas antes de 1978", "Todos los colores de pintura usados", "La marca de pintura", "No se requiere nada"]', 0, 'Federal law requires disclosure of known lead-based paint hazards for residential properties built before 1978.', 'La ley federal requiere la divulgación de peligros conocidos de pintura a base de plomo para propiedades residenciales construidas antes de 1978.', true, '2026-01-14 22:36:13.223496', '2026-01-14 22:36:13.223496') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('68782151-c726-43ca-b29f-6bec09175cb6', 'real_estate', NULL, 'What should be disclosed about a property in a flood zone?', '¿Qué debe divulgarse sobre una propiedad en una zona de inundación?', '["That the property is in a designated flood zone and may require flood insurance", "Nothing special is required", "Only if there has been flooding", "Only for commercial properties"]', '["Que la propiedad está en una zona de inundación designada y puede requerir seguro contra inundaciones", "No se requiere nada especial", "Solo si ha habido inundaciones", "Solo para propiedades comerciales"]', 0, 'Properties in FEMA-designated flood zones must be disclosed, and flood insurance may be required for mortgage approval.', 'Las propiedades en zonas de inundación designadas por FEMA deben ser divulgadas, y puede requerirse seguro contra inundaciones para la aprobación de la hipoteca.', true, '2026-01-14 22:36:13.24271', '2026-01-14 22:36:13.24271') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('68afff3c-ac25-4b1c-87f8-919c2b080353', 'real_estate', NULL, 'What does CMA stand for in real estate?', '¿Qué significa CMA en bienes raíces?', '["Comparative Market Analysis", "Commercial Market Assessment", "Certified Market Appraisal", "Competitive Marketing Agreement"]', '["Análisis Comparativo de Mercado", "Evaluación del Mercado Comercial", "Tasación Certificada del Mercado", "Acuerdo de Mercadeo Competitivo"]', 0, 'A CMA (Comparative Market Analysis) is an evaluation of similar homes in the area to help determine listing price.', 'Un CMA (Análisis Comparativo de Mercado) es una evaluación de casas similares en el área para ayudar a determinar el precio de listado.', true, '2026-01-14 18:28:35.362485', '2026-01-14 18:28:35.362485') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6b9c1060-9552-421f-a264-4dc49bfa434e', 'real_estate', NULL, 'What is a lease?', '¿Qué es un arrendamiento?', '["A contract granting possession and use of property for a specified time in exchange for rent", "A deed", "A mortgage", "A sale agreement"]', '["Un contrato que otorga posesión y uso de propiedad por un tiempo especificado a cambio de alquiler", "Una escritura", "Una hipoteca", "Un acuerdo de venta"]', 0, 'A lease is a contract that grants the tenant the right to use and possess property for a specified period in exchange for rent.', 'Un arrendamiento es un contrato que otorga al inquilino el derecho de usar y poseer propiedad por un período especificado a cambio de alquiler.', true, '2026-01-14 22:36:13.384865', '2026-01-14 22:36:13.384865') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6c6786f0-24be-47b6-b304-0a5cb1378c76', 'real_estate', NULL, 'What is blockbusting?', '¿Qué es el blockbusting?', '["Inducing panic selling by suggesting neighborhood demographic changes", "A construction technique", "A marketing strategy", "A legal sales practice"]', '["Inducir venta de pánico sugiriendo cambios demográficos del vecindario", "Una técnica de construcción", "Una estrategia de mercadeo", "Una práctica legal de ventas"]', 0, 'Blockbusting is the illegal practice of inducing homeowners to sell by suggesting that minority groups are moving into the neighborhood.', 'El blockbusting es la práctica ilegal de inducir a propietarios a vender sugiriendo que grupos minoritarios se están mudando al vecindario.', true, '2026-01-14 18:28:35.538462', '2026-01-14 18:28:35.538462') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7079c928-9128-4abc-aee8-3ae8bbcd1e03', 'real_estate', NULL, 'What is the primary purpose of a deed?', '¿Cuál es el propósito principal de una escritura?', '["To transfer ownership of real property", "To provide insurance coverage", "To establish a lease agreement", "To create a mortgage"]', '["Transferir la propiedad de bienes inmuebles", "Proporcionar cobertura de seguro", "Establecer un contrato de arrendamiento", "Crear una hipoteca"]', 0, 'A deed is a legal document that transfers ownership of real property from one party to another.', 'Una escritura es un documento legal que transfiere la propiedad de bienes inmuebles de una parte a otra.', true, '2026-01-14 18:28:35.272232', '2026-01-14 18:28:35.272232') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('709e3e55-08e6-45b0-827c-cd4712175a13', 'real_estate', NULL, 'What is a cloud on title?', '¿Qué es una nube sobre el título?', '["Any claim or encumbrance that could affect the owner''s rights", "Weather damage to property", "A type of insurance", "A mortgage payment"]', '["Cualquier reclamo o gravamen que podría afectar los derechos del propietario", "Daño climático a la propiedad", "Un tipo de seguro", "Un pago de hipoteca"]', 0, 'A cloud on title is any claim, lien, or encumbrance that could impair the owner''s title or make it doubtful.', 'Una nube sobre el título es cualquier reclamo, gravamen o carga que podría perjudicar el título del propietario o hacerlo dudoso.', true, '2026-01-14 18:28:35.338831', '2026-01-14 18:28:35.338831') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('70ba42ce-8efa-4e79-b153-0395a66ce749', 'real_estate', NULL, 'What is recording a deed?', '¿Qué es registrar una escritura?', '["Filing the deed in the county records to provide public notice of ownership", "Signing the deed", "Notarizing the deed", "Mailing the deed"]', '["Archivar la escritura en los registros del condado para proporcionar aviso público de propiedad", "Firmar la escritura", "Notarizar la escritura", "Enviar la escritura por correo"]', 0, 'Recording a deed means filing it with the county clerk''s office to provide public notice of the ownership transfer.', 'Registrar una escritura significa archivarla en la oficina del secretario del condado para proporcionar aviso público de la transferencia de propiedad.', true, '2026-01-14 22:36:13.321838', '2026-01-14 22:36:13.321838') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('70f8290c-4352-4459-8911-e4a77b8f73bb', 'real_estate', NULL, 'What is the Texas Association of Realtors (TAR)?', '¿Qué es la Asociación de Realtors de Texas (TAR)?', '["A professional trade association for real estate professionals in Texas", "The government licensing agency", "A title insurance company", "A mortgage lender"]', '["Una asociación comercial profesional para profesionales de bienes raíces en Texas", "La agencia de licencias del gobierno", "Una compañía de seguro de título", "Un prestamista hipotecario"]', 0, 'TAR is a voluntary professional trade association that provides resources, advocacy, and education for real estate professionals.', 'TAR es una asociación comercial profesional voluntaria que proporciona recursos, defensa y educación para profesionales de bienes raíces.', true, '2026-01-14 22:36:58.977251', '2026-01-14 22:36:58.977251') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('72416c99-c030-4d21-b580-6c0c71cb4095', 'real_estate', NULL, 'The income approach to value is used primarily for:', 'El enfoque de ingresos para el valor se utiliza principalmente para:', '["Investment and income-producing properties", "Single-family homes only", "Vacant land only", "New construction only"]', '["Propiedades de inversión y productoras de ingresos", "Solo casas unifamiliares", "Solo terrenos vacíos", "Solo nueva construcción"]', 0, 'The income approach is primarily used to value income-producing properties based on the income they generate.', 'El enfoque de ingresos se utiliza principalmente para valorar propiedades productoras de ingresos basándose en los ingresos que generan.', true, '2026-01-14 22:36:13.180442', '2026-01-14 22:36:13.180442') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7259a034-6de4-4a6a-b8ce-81cc01c1fedf', 'real_estate', NULL, 'What is a Comparative Market Analysis (CMA)?', '¿Qué es un Análisis Comparativo de Mercado (CMA)?', '["An informal estimate of property value prepared by a real estate agent", "An official appraisal", "A government assessment", "A title search"]', '["Una estimación informal del valor de la propiedad preparada por un agente de bienes raíces", "Una tasación oficial", "Una evaluación del gobierno", "Una búsqueda de título"]', 0, 'A CMA is an informal estimate of market value based on sales of comparable properties, prepared by a real estate agent.', 'Un CMA es una estimación informal del valor de mercado basada en ventas de propiedades comparables, preparada por un agente de bienes raíces.', true, '2026-01-14 22:36:13.184275', '2026-01-14 22:36:13.184275') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7379df14-c20d-4ebc-b3a7-09734be1be04', 'real_estate', NULL, 'What does ''escrow'' mean in a real estate transaction?', '¿Qué significa ''escrow'' en una transacción inmobiliaria?', '["A type of property insurance", "A neutral third party holding funds until conditions are met", "A real estate agent''s commission", "The down payment on a property"]', '["Un tipo de seguro de propiedad", "Un tercero neutral que retiene fondos hasta que se cumplan las condiciones", "La comisión de un agente inmobiliario", "El pago inicial de una propiedad"]', 1, 'Escrow is a financial arrangement where a third party holds and regulates payment of funds until all conditions of a transaction are met.', 'El escrow es un acuerdo financiero donde un tercero retiene y regula el pago de fondos hasta que se cumplan todas las condiciones de una transacción.', true, '2026-01-14 16:50:01.88016', '2026-01-14 16:50:01.88016') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('754e57d5-fef7-41c7-86d0-308d1cb48df0', 'real_estate', NULL, 'What is an abstract of title?', '¿Qué es un resumen de título?', '["A historical summary of all recorded documents affecting a property''s title", "A purchase agreement", "A mortgage document", "An insurance policy"]', '["Un resumen histórico de todos los documentos registrados que afectan el título de una propiedad", "Un contrato de compra", "Un documento hipotecario", "Una póliza de seguro"]', 0, 'An abstract of title is a condensed history of the title including deeds, mortgages, liens, and other documents affecting ownership.', 'Un resumen de título es una historia condensada del título incluyendo escrituras, hipotecas, gravámenes y otros documentos que afectan la propiedad.', true, '2026-01-14 18:28:35.548491', '2026-01-14 18:28:35.548491') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7579e0e0-b21b-4c25-89e7-c952435e093d', 'real_estate', NULL, 'What is MLS (Multiple Listing Service)?', '¿Qué es el MLS (Servicio de Listado Múltiple)?', '["A database of properties for sale shared among real estate brokers", "A government property registry", "A mortgage application system", "A property tax database"]', '["Una base de datos de propiedades en venta compartida entre corredores de bienes raíces", "Un registro de propiedades del gobierno", "Un sistema de solicitud de hipotecas", "Una base de datos de impuestos sobre propiedades"]', 0, 'The MLS is a cooperative database where real estate brokers share property listings and offer compensation to buyer''s agents.', 'El MLS es una base de datos cooperativa donde los corredores de bienes raíces comparten listados de propiedades y ofrecen compensación a los agentes de compradores.', true, '2026-01-14 22:36:58.982285', '2026-01-14 22:36:58.982285') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('783b271e-b616-4b5a-b5d5-78222dea053d', 'real_estate', NULL, 'What is the difference between a listing agent and a buyer''s agent?', '¿Cuál es la diferencia entre un agente de listado y un agente del comprador?', '["There is no difference", "A listing agent represents the seller, while a buyer''s agent represents the buyer", "A listing agent only works with commercial properties", "A buyer''s agent is not licensed"]', '["No hay diferencia", "Un agente de listado representa al vendedor, mientras que un agente del comprador representa al comprador", "Un agente de listado solo trabaja con propiedades comerciales", "Un agente del comprador no tiene licencia"]', 1, 'A listing agent represents the seller''s interests, while a buyer''s agent represents the buyer''s interests in a real estate transaction.', 'Un agente de listado representa los intereses del vendedor, mientras que un agente del comprador representa los intereses del comprador en una transacción inmobiliaria.', true, '2026-01-14 16:50:01.887447', '2026-01-14 16:50:01.887447') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('789fb61e-6686-472c-be73-b739cfa9c2e7', 'real_estate', NULL, 'What is eminent domain used for?', '¿Para qué se usa el dominio eminente?', '["Acquiring private property for public use such as roads, schools, or utilities", "Private development", "Personal use", "Commercial development only"]', '["Adquirir propiedad privada para uso público como carreteras, escuelas o servicios públicos", "Desarrollo privado", "Uso personal", "Solo desarrollo comercial"]', 0, 'Eminent domain allows government to take private property for public purposes like roads, utilities, and public buildings.', 'El dominio eminente permite al gobierno tomar propiedad privada para propósitos públicos como carreteras, servicios públicos y edificios públicos.', true, '2026-01-14 22:36:13.381357', '2026-01-14 22:36:13.381357') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('78b4703d-116d-451c-8ef2-a99b1eef7fc7', 'real_estate', NULL, 'What is a variance in zoning?', '¿Qué es una variación en zonificación?', '["Permission to deviate from zoning requirements", "A type of easement", "A deed restriction", "A building permit"]', '["Permiso para desviarse de los requisitos de zonificación", "Un tipo de servidumbre", "Una restricción de escritura", "Un permiso de construcción"]', 0, 'A variance is permission granted by a zoning board to deviate from strict zoning requirements due to hardship.', 'Una variación es un permiso otorgado por una junta de zonificación para desviarse de los requisitos estrictos de zonificación debido a dificultades.', true, '2026-01-14 22:36:13.350484', '2026-01-14 22:36:13.350484') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7ac9c939-608a-46ac-bff5-d5c4dbea9789', 'real_estate', NULL, 'What is the difference between a fixed-rate and adjustable-rate mortgage?', '¿Cuál es la diferencia entre una hipoteca de tasa fija y una de tasa ajustable?', '["Fixed-rate stays the same; adjustable-rate can change over time", "They are exactly the same", "Fixed-rate is always higher", "Adjustable-rate never changes"]', '["La tasa fija permanece igual; la tasa ajustable puede cambiar con el tiempo", "Son exactamente iguales", "La tasa fija siempre es más alta", "La tasa ajustable nunca cambia"]', 0, 'A fixed-rate mortgage has a constant interest rate, while an adjustable-rate mortgage (ARM) has a rate that can change based on market conditions.', 'Una hipoteca de tasa fija tiene una tasa de interés constante, mientras que una hipoteca de tasa ajustable (ARM) tiene una tasa que puede cambiar según las condiciones del mercado.', true, '2026-01-14 22:36:13.113877', '2026-01-14 22:36:13.113877') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7af7b07a-c1be-4872-a46f-eaae74549f77', 'real_estate', NULL, 'FHA loans are designed primarily for:', 'Los préstamos FHA están diseñados principalmente para:', '["First-time homebuyers and those with lower credit scores", "Wealthy investors", "Commercial properties only", "Vacation homes only"]', '["Compradores de vivienda por primera vez y aquellos con puntajes de crédito más bajos", "Inversionistas adinerados", "Solo propiedades comerciales", "Solo casas vacacionales"]', 0, 'FHA loans are designed to help first-time homebuyers and borrowers with lower credit scores or smaller down payments.', 'Los préstamos FHA están diseñados para ayudar a compradores de vivienda por primera vez y prestatarios con puntajes de crédito más bajos o pagos iniciales más pequeños.', true, '2026-01-14 22:36:13.11011', '2026-01-14 22:36:13.11011') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7d1e54bd-c6c1-43ac-8894-ca0e8fbe413c', 'real_estate', NULL, 'The Third Party Financing Addendum specifies:', 'El Anexo de Financiamiento de Terceros especifica:', '["The buyer''s financing terms and conditions", "The seller''s existing mortgage", "The title company''s requirements", "The appraisal requirements"]', '["Los términos y condiciones de financiamiento del comprador", "La hipoteca existente del vendedor", "Los requisitos de la compañía de títulos", "Los requisitos de tasación"]', 0, 'The Third Party Financing Addendum outlines the buyer''s financing terms including loan type, amount, interest rate, and approval timeline.', 'El Anexo de Financiamiento de Terceros describe los términos de financiamiento del comprador incluyendo tipo de préstamo, monto, tasa de interés y plazo de aprobación.', true, '2026-01-14 22:36:13.088424', '2026-01-14 22:36:13.088424') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7d219fec-40f3-4465-b1ae-54034fa3edcf', 'real_estate', NULL, 'Which of the following is NOT a TREC promulgated form?', '¿Cuál de los siguientes NO es un formulario promulgado por TREC?', '["Commercial lease agreement", "One to Four Family Residential Contract", "Seller''s Disclosure Notice", "Addendum for Property Subject to Mandatory Membership"]', '["Contrato de arrendamiento comercial", "Contrato Residencial de Una a Cuatro Familias", "Aviso de Divulgación del Vendedor", "Anexo para Propiedad Sujeta a Membresía Obligatoria"]', 0, 'Commercial lease agreements are not TREC promulgated forms; they are typically prepared by attorneys.', 'Los contratos de arrendamiento comercial no son formularios promulgados por TREC; típicamente son preparados por abogados.', true, '2026-01-14 22:36:13.078338', '2026-01-14 22:36:13.078338') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7e6c5240-69cf-42ec-8538-beb047a8e871', 'real_estate', NULL, 'A sales agent''s license is automatically inactivated when:', 'La licencia de un agente de ventas se inactiva automáticamente cuando:', '["The sponsoring broker''s license expires or is revoked", "The agent moves to a different city", "The agent sells fewer than 3 properties per year", "The agent reaches age 65"]', '["La licencia del corredor patrocinador expira o es revocada", "El agente se muda a otra ciudad", "El agente vende menos de 3 propiedades por año", "El agente alcanza los 65 años"]', 0, 'A sales agent''s license is automatically placed on inactive status when their sponsoring broker''s license expires, is suspended, or is revoked.', 'La licencia de un agente de ventas se coloca automáticamente en estado inactivo cuando la licencia de su corredor patrocinador expira, se suspende o se revoca.', true, '2026-01-14 22:36:12.976013', '2026-01-14 22:36:12.976013') ON CONFLICT (id) DO NOTHING;
